    "faqData.category.consultation": "Consultation",
    "faqData.category.payment": "Payment",
    "faqData.category.privacy": "Privacy & data",
    "faqData.category.recovery": "Recovery & immune care",
    "faqData.category.service": "About healwith",
    "faqData.category.treatment": "Treatment",
    "faqData.category.visa": "Visa & stay",
    "faqData.consultation1.a": "Within one business day, in your preferred language. For urgent cases (e.g. time-sensitive diagnosis), we expedite to a few hours.",
    "faqData.consultation1.q": "How fast do you respond to inquiries?",
    "faqData.consultation2.a": "Yes. After intake, we arrange a pre-consultation video call with the matched specialist — with simultaneous medical interpretation in your language (Korean-Russian, Korean-English, etc.).",
    "faqData.consultation3.q": "How do I send my medical records (CT scans, biopsy results)?",
    "faqData.consultation3.a": "Attach them in step 2 of the inquiry form — PDF, JPG or PNG, up to 10 files. You can also send them later: after you submit, your coordinator contacts you and you can add files to the same inquiry. Files are encrypted and shared only with the hospital you choose. If a file is too large, split it or send the key pages first — a diagnosis summary, pathology report and recent imaging are usually enough to start.",
    "faqData.consultation2.q": "Can I speak to a doctor before traveling?",
    "faqData.payment1.a": "You pay only the hospital, directly, for your treatment (in KRW, by credit card, cash, or wire). healwith does not charge patients any service or concierge fee — you pay us nothing.",
    "faqData.payment1.q": "How does payment work?",
    "faqData.payment2.a": "Yes. Under Article 8(2) of Korea's Act on Overseas Expansion of Healthcare and Attraction of Foreign Patients, the registered attracting medical institution (the hospital) must provide a treatment contract and an estimated treatment cost before any treatment contract is signed. healwith, as a registered facilitator, delivers that quotation to you in your language or English and walks you through it. It details treatment costs and the refund policy. The facilitator fee, a statutory disclosure item, is the amount the Company receives from the hospital — it is not charged to you.",
    "faqData.payment3.q": "What happens if I cancel?",
    "faqData.payment3.a": "Nothing is charged by healwith. We never take a fee from patients, so there is no cancellation fee on our side — consultation, hospital matching, the pre-consultation video call and the written estimate are all free, and you can stop at any point before signing a treatment contract at no cost. If you have already paid a deposit directly to a hospital, that hospital's own refund terms apply; those terms are written in the estimate you receive before you sign anything.",
    "faqData.payment2.q": "Will I get a written estimate before committing?",
    "faqData.privacy1.a": "End-to-end encrypted (TLS 1.3 in transit, AES-256 at rest). Compliant with Korean PIPA, Kazakhstan Law 94-V, and EU GDPR. Sensitive health data requires explicit separate consent, is shared only with hospitals you choose, and is deleted after service completion.",
    "faqData.privacy1.q": "How do you protect my medical data?",
    "faqData.privacy2.a": "Yes. You can request access, correction, or deletion of your personal data at any time by contacting our DPO (admin@healwith.co.kr). Medical records retained by hospitals are subject to their own legal retention periods (typically 10 years under Korean Medical Service Act §22).",
    "faqData.privacy2.q": "Can I delete my data later?",
    "faqData.recovery1.a": "At a cooperating university/general hospital you receive diagnosis, surgery, and chemotherapy. At our partner immune-care hospitals (Immune Hospital of Korean Medicine) you recover afterward — with Korean-medicine immunotherapy, pain rehabilitation, nutrition, and side-effect management. healwith links both into one continuous care path.",
    "faqData.recovery1.q": "What's the difference between the surgery hospital and the immune-care hospital?",
    "faqData.recovery2.a": "Korean-medicine immunotherapy, thermotherapy, pain rehabilitation, customized nutrition and inpatient meals, and physical/psychological recovery support — tailored to your cancer type and condition after surgery or chemotherapy. The exact program is set by the hospital's medical team.",
    "faqData.recovery2.q": "What treatments can I receive at the immune-care hospital?",
    "faqData.recovery3.a": "The weeks after surgery or chemotherapy are when immunity is lowest and side effects appear. Structured recovery care — monitored nutrition, immune and pain management, and a calm environment — can support a smoother recovery compared to managing alone. healwith coordinates surgery and recovery so the transition is seamless, with interpretation throughout.",
    "faqData.recovery3.q": "Why recover in Korea after surgery instead of returning home right away?",
    "faqData.recovery4.a": "It depends on your condition — recovery care can be inpatient or outpatient. Programs typically range from a few days to several weeks. Your coordinator and the medical team set a plan that fits your treatment timeline and visa, and adjust it as you recover.",
    "faqData.recovery4.q": "Do I have to be admitted as an inpatient, and how long does recovery care take?",
    "faqData.service1.a": "healwith is a medical concierge platform that helps international cancer patients access care at Korea's top oncology hospitals. We handle hospital matching, visa support, translation, and end-to-end coordination — so you focus on recovery.",
    "faqData.service1.q": "What exactly is healwith?",
    "faqData.service2.a": "No. healwith is a registered international patient facilitator (Reg. A-2026-01-02-06761 by the Mayor of Seoul). We connect you with licensed Korean hospitals, but all diagnosis and treatment is performed by the hospital's medical team.",
    "faqData.service2.q": "Is healwith a hospital?",
    "faqData.service3.a": "healwith is free for patients. From your first inquiry through post-treatment follow-up, we never charge you a service or concierge fee. You pay only the hospital, directly, for your treatment — healwith is compensated by its partner hospitals.",
    "faqData.service3.q": "How much does healwith cost?",
    "faqData.treatment1.a": "Primary focus on stomach, breast, liver, lung, thyroid, and colorectal cancer — where Korea has world-leading survival rates. We also coordinate for other oncology cases through our partner hospital network.",
    "faqData.treatment1.q": "What cancer types does healwith specialize in?",
    "faqData.treatment2.a": "Based on your diagnosis, stage, language needs, budget, and timeline, our matching algorithm suggests 2–3 suitable hospitals. A coordinator reviews the match and you make the final choice.",
    "faqData.treatment2.q": "How do I know which hospital is right for me?",
    "faqData.visa1.a": "It depends on nationality. Most patients need a medical visa (C-3-3 for short-term under 90 days, G-1 for longer treatment). healwith prepares the invitation letter and supports the entire application.",
    "faqData.visa1.q": "Do I need a visa to receive treatment in Korea?",
    "faqData.visa2.a": "Yes. We assist one or more accompanying family members with their visa application (usually C-3-3 or C-3-9) and coordinate accommodations for them during your treatment.",
    "faqData.visa2.q": "Can I bring a caregiver or family member?",
