    "careJourney.closingBody": "One minute is enough. A coordinator will contact you in your preferred language.",
    "careJourney.closingCta": "Request a consultation",
    "careJourney.closingTitle": "Let's decide together where your journey begins",
    "careJourney.eyebrow": "Total Care Concierge",
    "careJourney.heroCta": "Start a consultation",
    "careJourney.heroLede": "healwith isn't a service that just picks a hospital for you. From online consultation before you arrive, through diagnosis, surgery, and immune recovery, to post-return care — we design and accompany the entire cancer treatment journey with you.",
    "careJourney.heroTitle": "From diagnosis to recovery —\na seamless care journey",
    "careJourney.modelBody": "Cancer treatment doesn't end with a single surgery. healwith connects Korean Medicine hospitals specializing in immune and rehabilitation care with cooperating university hospitals focused on surgery and chemotherapy — as one network — so each stage of care follows your diagnosis. You never have to search for a new hospital each time.",
    "careJourney.modelTitle": "Why a 'care path', not 'hospital matching'",
    "careJourney.partnerImmune1": "Immune Hospital Gangseo",
    "careJourney.partnerImmune2": "Immune Hospital Sinchon",
    "careJourney.partnerImmune3": "Immune Hospital Gwangmyeong",
    "careJourney.partnerImmune4": "Immune Hospital Seongdong",
    "careJourney.partnerImmuneGroupTitle": "Partner Korean Medicine Hospitals",
    "careJourney.partnerLede": "Surgery and chemotherapy at cooperating university hospitals; immune and rehabilitation care at Immune Hospital — connected as one seamless network.",
    "careJourney.partnerTitle": "Our hospital network",
    "careJourney.partnerUniversity1": "Ewha Seoul Hospital",
    "careJourney.partnerUniversity2": "Ewha Mokdong Hospital",
    "careJourney.partnerUniversity3": "Korea Univ. Guro Hospital",
    "careJourney.partnerUniversity4": "Sinchon Severance Hospital",
    "careJourney.partnerUniversityLabel": "Cooperating University Hospitals",
    "careJourney.stat1Label": "5-year cancer survival rate (2019–2023)",
    "careJourney.stat1Value": "73.7%",
    "careJourney.stat2Label": "international patients chose Korea in 2025",
    "careJourney.stat2Value": "2.01M+",
    "careJourney.statsSource": "Sources: National Cancer Center Korea (national cancer registry); KHIDI foreign patient statistics",
    "careJourney.statsTitle": "Korea's cancer care, in numbers",
    "careJourney.step1Body": "Our AI assistant and coordinators respond in 6 languages. Resolve your questions from home, before you travel to Korea.",
    "careJourney.step1Title": "Online consultation",
    "careJourney.step2Body": "Our partner medical teams review your existing records and explain the treatment direction available in Korea.",
    "careJourney.step2Title": "Remote diagnosis",
    "careJourney.step3Body": "If surgery is needed, we connect you to a cooperating university hospital; immune care and rehabilitation continue at the Korean Medicine hospital. We design the right path with you.",
    "careJourney.step3Title": "Care path design",
    "careJourney.step4Body": "During your stay in Korea, coordinators support you with medical interpretation, hospital visits, and daily-life assistance.",
    "careJourney.step4Title": "On-site companionship",
    "careJourney.step5Body": "After you return home, follow-up care continues via remote consultation. Treatment doesn't end with a single visit.",
    "careJourney.step5Title": "Post-return care",
    "careJourney.stepsTitle": "Your care journey, in 5 steps",
    "careJourney.whyCare1Body": "Specialists manage weakened immunity, pain, and side effects after surgery or chemo — through Korean-medicine immunotherapy and pain rehabilitation, step by step, tailored to your condition.",
    "careJourney.whyCare1Title": "Structured immune & rehab care",
    "careJourney.whyCare2Body": "Inpatient meals and nutrition planning matched to your cancer type and recovery state help rebuild strength. We also consider international patients' dietary needs.",
    "careJourney.whyCare2Title": "Tailored nutrition & meals",
    "careJourney.whyCare3Body": "Unlike a busy tertiary hospital, you can focus on recovery in a calm setting — with interpretation and a coordinator dedicated to international patients.",
    "careJourney.whyCare3Title": "Calm recovery environment & language support",
    "careJourney.whyCareLede": "Cancer treatment doesn't end with surgery or chemotherapy. How you manage weakened immunity and side effects during recovery shapes what comes next. healwith's partner Korean Medicine hospitals specialize in this recovery stage.",
    "careJourney.whyCareTitle": "After surgery, why immune & rehabilitation care matters",
