    "seo.home.desc": "Korean cancer care concierge for international patients — video pre-consultation with top oncologists, 6-language support, full-journey care.",
    "seo.treatments.title": "Cancer Treatment Guide — Korean & Integrative Care | healwith",
    "seo.treatments.desc": "Specialized care for 6 cancer types — breast, gynecologic, digestive, liver, lung, thyroid — with Korean Medicine integrative immune therapy.",
