    "seo.about.title": "About healwith — Korea Cancer Care Concierge",
    "seo.about.desc": "healwith connects international cancer patients with trusted Korean hospitals — oncologist video consultation, 6-language interpretation, and care from diagnosis to follow-up.",
    "seo.contact.title": "Contact Us — Patients and Partners | healwith",
