    // otherAccount·goHome 은 그쪽 GATE_TR 값을 문자 그대로 가져왔다. 두 화면이 다른 말을 하면 안 된다.
    // ⚠️ heading 을 「{영역} 전용」 치환 템플릿으로 만들지 마라 — t() 는 치환을 지원하지 않고,
