    "km.viewAll": "View All Korean Medicine Treatments",
    "km.hero.title": "Discover Traditional Korean Medicine",
    "km.hero.highlight": "Rooted in 1,000 Years of Healing",
    "km.hero.subtitle": "Experience Korea's unique holistic medical system — herbal formulas, acupuncture, and personalized wellness programs curated for international patients.",
    "km.cta": "Get a Free Treatment Plan",
    "km.section.whatIs": "What is Korean Medicine?",
    "km.section.whatIsDesc": "Korean Medicine (한방/韓方) is Korea's unique traditional medical system with over 1,000 years of history. It combines herbal medicine, acupuncture, moxibustion, and cupping therapies to treat the root cause of illness by restoring balance in the body. Today, it is practiced in fully licensed hospitals regulated by the Korean government.",
    "km.section.whyKorea": "Why Korea for Traditional Medicine?",
    "km.section.hospitals": "Partner Korean Medicine Hospitals",
    "km.section.treatments": "Korean Medicine Treatment Programs",
    "km.section.faq": "Frequently Asked Questions",
    "km.faq.q1": "What is Korean Medicine (Hanbang)?",
    "km.faq.a1": "Korean Medicine (한방/韓方) is Korea's unique traditional medical system with over 1,000 years of history. It uses herbal medicine, acupuncture, moxibustion, and cupping to treat the root cause of illness by restoring balance in the body.",
    "km.faq.q2": "Is Korean Medicine safe?",
    "km.faq.a2": "Yes. All Korean Medicine hospitals in Korea are licensed and regulated by the Ministry of Health and Welfare. Practitioners hold doctoral-level degrees and follow strict safety protocols with certified, quality-controlled herbal ingredients.",
    "km.faq.q3": "How is it different from Traditional Chinese Medicine?",
    "km.faq.a3": "While they share historical roots, Korean Medicine (韓方) has evolved independently, featuring Sasang constitutional medicine (사상체질의학), unique herbal formulations, and is more regulated under Korea's national healthcare system.",
    "km.faq.q4": "Do I need to speak Korean?",
    "km.faq.a4": "No. Partner hospitals provide English and Chinese translation services with international patient coordinators to assist throughout your visit.",
    "km.faq.q5": "How long should I stay in Korea?",
    "km.faq.a5": "Treatment duration varies: Immune Boost and Wellness programs typically require 5-7 days, Postpartum Recovery 2-4 weeks. Programs can be customized to fit your schedule.",
    "km.diff.regulated": "Government-Regulated",
    "km.diff.regulatedDesc": "All Korean Medicine hospitals are licensed and regulated by the Ministry of Health and Welfare with strict safety standards.",
    "km.diff.unique": "Unique Sasang Medicine",
    "km.diff.uniqueDesc": "Korea's own constitutional medicine system classifies patients into four body types for personalized treatment.",
    "km.diff.modern": "Modern Integration",
    "km.diff.modernDesc": "Korean Medicine hospitals combine traditional therapies with modern diagnostic technology for evidence-based care.",
