    "careJourney.heroCta": "상담 시작하기",
    "careJourney.heroLede": "healwith는 병원 하나를 골라드리는 곳이 아닙니다. 한국 도착 전 온라인 상담부터 진단·수술·면역 회복, 귀국 후 관리까지 — 암 치료의 전 과정을 함께 설계하고 동행합니다.",
    "careJourney.heroTitle": "진단부터 회복까지,\n끊김 없는 치료 여정",
    "careJourney.modelBody": "암 치료는 한 번의 수술로 끝나지 않습니다. healwith는 면역·재활 전문 한방병원과 수술·항암 중심의 협진 대학병원이 하나의 네트워크로 연결되어, 진단 결과에 따라 필요한 치료를 단계별로 이어드립니다. 환자는 매번 새 병원을 찾을 필요가 없습니다.",
