    "careJourney.whyCare1Title": "체계적인 면역·재활 관리",
    "careJourney.whyCare2Body": "암종과 회복 상태에 맞춘 입원식과 영양 관리로 체력을 보강합니다. 해외 환자의 식문화도 함께 고려합니다.",
