    "seo.home.title": "healwith 힐위드 | 해외 암환자 한국 치료 컨시어지",
    "seo.home.desc": "힐위드(healwith) — 해외 암환자를 위한 한국 암 치료 컨시어지. 종양 전문의 화상 사전상담, 6개 언어 지원, 진단부터 사후관리까지 토탈 케어.",
    "seo.treatments.title": "암종별 치료 안내 — 한국 암 치료와 한방 통합 케어 | healwith",
    "seo.treatments.desc": "유방·부인암, 소화기, 간, 폐, 갑상선 등 6개 암종 전문 치료 안내. 한방 통합 면역치료.",
    "seo.hospitals.title": "협력 병원 — healwith 파트너 의료기관",
    "seo.hospitals.desc": "healwith 파트너 면력한방병원과 협진 암 전문 병원. 한방 면역치료부터 암 수술·항암까지 원스톱 케어.",
    "seo.telemedicine.title": "원격협진 — 한국 전문의 실시간 영상 상담 | healwith",
    "seo.telemedicine.desc": "한국 종양 전문의와 실시간 영상 사전상담. 6개 언어 통역 지원. 방문 전 먼저 연결.",
    "seo.careJourney.title": "치료 여정 — 진단부터 회복까지 토탈 케어 | healwith",
    "seo.careJourney.desc": "한국에서의 암 치료 전 과정 — 진단·상담부터 치료, 비자, 사후관리까지.",
    "seo.insurance.title": "보험으로 받는 한국 암치료 | healwith",
    "seo.insurance.desc": "중증질환 보험으로 받는 한국 암치료. 치료비·항공·숙박까지 보험이 커버할 수 있고, healwith가 한국 측 병원·통역·케어를 조직합니다.",
    "seo.faq.title": "자주 묻는 질문 — 해외 환자가 가장 많이 묻는 것 | healwith",
    "seo.faq.desc": "상담·한국 치료·의료비자·결제·개인정보까지. 해외 암환자가 오기 전에 가장 많이 묻는 질문에 답합니다.",
    "seo.visa.title": "한국 의료비자 안내 — C-3-3·G-1-10 | healwith",
    "seo.visa.desc": "어떤 의료비자가 필요한지, 준비 서류, 처리 기간, 대사관 연락처까지. 치료를 위해 한국에 오는 환자를 위한 안내.",
    "seo.about.title": "healwith 소개 — 해외 암환자 한국 치료 컨시어지",
    "seo.about.desc": "healwith는 해외 암환자를 검증된 한국 병원과 연결합니다. 종양 전문의 화상 상담, 6개 언어 통역, 진단부터 사후관리까지.",
    "seo.contact.title": "문의하기 — 환자·파트너 | healwith",
    "seo.contact.desc": "한국 치료, 종양 전문의 세컨드 오피니언, 병원·에이전시 제휴 문의. 환자분 언어로 답변합니다.",
    "seo.terms.title": "이용약관 | healwith",
    "seo.terms.desc": "healwith 의료 컨시어지·병원 매칭·통역 서비스 이용에 관한 약관입니다.",
    "seo.privacy.title": "개인정보처리방침 | healwith",
    "seo.privacy.desc": "healwith가 개인정보와 의료정보를 어떻게 수집·이용·암호화하고 보호하는지 안내합니다.",
    "seo.cookies.title": "쿠키 정책 | healwith",
    "seo.cookies.desc": "healwith가 사용하는 쿠키의 종류와 목적, 그리고 이용자가 직접 선택할 수 있는 방법을 안내합니다.",
    "seo.medicalDisclaimer.title": "의료 정보 고지 | healwith",
