    "km.viewAll": "한방 시술 전체 보기",
    "km.hero.title": "한국 전통 한방 의학을 만나보세요",
    "km.hero.highlight": "천 년의 치유 전통",
    "km.hero.subtitle": "한국 고유의 전인적 의료 시스템을 경험하세요 — 한약, 침술, 맞춤형 웰니스 프로그램을 해외 환자를 위해 준비했습니다.",
    "km.cta": "무료 치료 플랜 받기",
    "km.section.whatIs": "한방 의학이란?",
    "km.section.whatIsDesc": "한방(韓方)은 1,000년 이상의 역사를 가진 한국 고유의 전통 의료 시스템입니다. 한약, 침술, 뜸, 부항 등을 결합하여 몸의 균형을 회복시켜 질병의 근본 원인을 치료합니다. 현재 한국 정부의 인허가를 받은 병원에서 시행되고 있습니다.",
    "km.section.whyKorea": "왜 한국에서 한방 치료를?",
    "km.section.hospitals": "제휴 한방 병원",
    "km.section.treatments": "한방 치료 프로그램",
    "km.section.faq": "자주 묻는 질문",
    "km.faq.q1": "한의학(한방)이란 무엇인가요?",
    "km.faq.a1": "한의학(한방/韓方)은 1,000년 넘는 역사를 가진 한국 고유의 전통 의학 체계입니다. 한약·침·뜸·부항으로 몸의 균형을 회복해 질병의 근본 원인을 치료합니다.",
    "km.faq.q2": "한의학 치료는 안전한가요?",
    "km.faq.a2": "네. 한국의 모든 한방병원은 보건복지부의 허가와 규제를 받습니다. 한의사는 박사급 학위를 갖추고 있으며, 인증된 품질관리 한약재로 엄격한 안전 절차를 따릅니다.",
    "km.faq.q3": "중의학(중국 전통의학)과 무엇이 다른가요?",
    "km.faq.a3": "역사적 뿌리는 같지만 한의학(韓方)은 독자적으로 발전해 왔습니다. 사상체질의학과 고유한 처방을 갖추고 있으며, 한국 국가 의료체계 안에서 더 엄격하게 관리됩니다.",
    "km.faq.q4": "한국어를 할 줄 알아야 하나요?",
    "km.faq.a4": "아니요. 제휴 병원은 영어·중국어 통역과 국제환자 코디네이터를 제공해 방문 전 과정을 돕습니다.",
    "km.faq.q5": "한국에 얼마나 머물러야 하나요?",
    "km.faq.a5": "치료 기간은 프로그램마다 다릅니다. 면역 강화·웰니스 프로그램은 보통 5-7일, 산후조리는 2-4주가 걸립니다. 일정에 맞춰 조정할 수 있습니다.",
    "km.diff.regulated": "정부 인허가 시스템",
    "km.diff.regulatedDesc": "모든 한방 병원은 보건복지부의 인허가를 받으며 엄격한 안전 기준을 준수합니다.",
    "km.diff.unique": "사상체질의학",
    "km.diff.uniqueDesc": "한국 고유의 체질의학 시스템으로 환자를 네 가지 체질로 분류하여 맞춤 치료를 제공합니다.",
    "km.diff.modern": "현대 의학과의 융합",
    "km.diff.modernDesc": "한방 병원은 전통 치료법과 현대 진단 기술을 결합하여 근거 중심 의료를 제공합니다.",
    "about.title": "healwith 소개",
    "about.subtitle": "글로벌 환자를 위한 AI 의료 컨시어지",
    "about.mission": "미션",
