    "costCalc.quoteTitle": "精确费用？免费咨询。",
    "faqData.category.consultation": "咨询",
    "faqData.category.payment": "付款",
    "faqData.category.privacy": "隐私数据",
    "faqData.category.recovery": "康复与免疫护理",
    "faqData.category.service": "关于 healwith",
    "faqData.category.treatment": "治疗",
    "faqData.category.visa": "签证住宿",
    "faqData.consultation1.a": "一个工作日内，以您偏好的语言回复。紧急情况几小时内响应。",
    "faqData.consultation1.q": "回复有多快？",
    "faqData.consultation2.a": "可以。申请后我们会安排与配对专科医生的预诊视频，并提供实时医疗翻译。",
    "faqData.consultation3.q": "我的病历（CT、活检报告）怎么发送？",
    "faqData.consultation3.a": "在咨询表第二步上传即可——支持 PDF、JPG、PNG，最多 10 个文件。也可以稍后提交：提交后协调员会与您联系，您可以在同一咨询中补充文件。文件加密保存，仅共享给您选择的医院。文件过大时可分开上传，或先发送关键资料——诊断摘要、病理报告和近期影像通常足以开始。",
    "faqData.consultation2.q": "可以在来韩前与医生通话吗？",
    "faqData.payment1.a": "您只需将治疗费直接支付给医院（韩币，信用卡/现金/汇款）。healwith 不向患者收取任何服务费或协调费——您无需向我们支付任何费用。",
    "faqData.payment1.q": "如何付款？",
    "faqData.payment2.a": "是。根据韩国《医疗海外拓展及外国人患者吸引支援法》第8条第2款，招引医疗机构（医院）须在签订诊疗合同前告知诊疗合同书与预估诊疗费。healwith 作为注册招引事业者，以您的语言或英文转交该报价单并协助确认。包含治疗费和退款政策。法定披露项「协调费」为公司向医院收取的金额，不向患者收取。",
    "faqData.payment3.q": "如果取消会怎样？",
    "faqData.payment3.a": "healwith 不会向您收取任何费用。我们从不向患者收费，因此我们这边没有取消费用——咨询、医院配对、术前视频问诊和书面报价均为免费，在签署治疗合同之前，您可以随时无偿终止。如果您已直接向医院支付了预付款，则适用该医院自己的退款规定；相关条款会写在您签字前收到的报价单中。",
    "faqData.payment2.q": "签约前能拿到报价单吗？",
    "faqData.privacy1.a": "端到端加密（传输 TLS 1.3，存储 AES-256）。符合韩国 PIPA、哈萨克斯坦 94-V 和 GDPR。敏感健康数据需单独明示同意，仅与您选择的医院共享，服务完成后删除。",
    "faqData.privacy1.q": "我的医疗数据如何保护？",
    "faqData.privacy2.a": "可以。您可随时向 DPO（admin@healwith.co.kr）申请查询、更正或删除。医院保存的医疗记录按《医疗法》§22 的法定保存期（通常10年）处理。",
    "faqData.privacy2.q": "以后能删除我的数据吗？",
    "faqData.recovery1.a": "在协诊大学/综合医院，您接受诊断、手术和化疗。在我们合作的免疫护理医院（免疫韩方医院），您在之后进行康复——韩方免疫治疗、疼痛康复、营养管理和副作用管理。healwith 将两者连接为一条连续护理路径。",
    "faqData.recovery1.q": "手术医院和免疫护理（韩方）医院有什么区别？",
    "faqData.recovery2.a": "韩方免疫治疗、热疗、疼痛康复、定制营养与住院餐、体力与心理康复支持——根据术后或化疗后的癌种与状态量身定制。具体方案由医院医疗团队确定。",
    "faqData.recovery2.q": "在免疫护理医院能接受哪些治疗？",
    "faqData.recovery3.a": "术后或化疗后的数周是免疫力最低、副作用出现的时期。系统的康复护理——营养监控、免疫与疼痛管理、安静环境——相比独自管理更有助于平稳康复。healwith 将手术与康复无缝衔接，全程提供翻译。",
    "faqData.recovery3.q": "为什么术后最好在韩国康复，而不是马上回国？",
    "faqData.recovery4.a": "取决于您的状态——可住院或门诊。通常从几天到数周不等。协调员和医疗团队会根据您的治疗时间表与签证制定方案，并随康复进展进行调整。",
    "faqData.recovery4.q": "康复护理需要住院吗？需要多长时间？",
    "faqData.service1.a": "healwith 是一家医疗协调平台，帮助国际癌症患者在韩国顶级肿瘤医院就诊。我们负责医院匹配、签证支持、翻译和全程协调。",
    "faqData.service1.q": "healwith 是什么？",
    "faqData.service2.a": "不是。healwith 是首尔市长注册的外国患者招揽服务商（注册号 A-2026-01-02-06761）。我们连接您和持牌韩国医院，但诊断和治疗由医院医疗团队执行。",
    "faqData.service2.q": "healwith 是医院吗？",
    "faqData.service3.a": "healwith 对患者完全免费。从初次咨询到治疗后随访，我们绝不向您收取任何服务费或协调费。您只需将治疗费直接支付给医院——healwith 由合作医院支付报酬。",
    "faqData.service3.q": "healwith 费用多少？",
    "faqData.treatment1.a": "主要专长：胃癌、乳腺癌、肝癌、肺癌、甲状腺癌、大肠癌——韩国在这些领域的生存率世界领先。其他癌症也通过合作医院网络协调。",
    "faqData.treatment1.q": "healwith 擅长哪些癌症？",
    "faqData.treatment2.a": "根据您的诊断、分期、语言、预算和时间，算法推荐2-3家医院。协调员审核，最终由您决定。",
    "faqData.treatment2.q": "如何选择适合我的医院？",
    "faqData.visa1.a": "取决于国籍。大多数患者需要医疗签证（C-3-3 短期（90天以内）、G-1 长期）。healwith 发放邀请函并协助全程申请。",
    "faqData.visa1.q": "在韩国治疗需要签证吗？",
    "faqData.visa2.a": "可以。我们协助一位或多位陪同家属申请签证（通常 C-3-3 或 C-3-9），并安排治疗期间的住宿。",
    "faqData.visa2.q": "可以带陪护或家人吗？",
