    "telemedicine.faqs.1.a": "不需要。远程协诊可在 PC、平板或手机的任意现代浏览器（Chrome、Safari、Edge）中运行。",
    "telemedicine.faqs.1.q": "需要下载应用吗？",
    "telemedicine.faqs.2.a": "专业医疗翻译会加入通话。我们支持俄语、哈萨克语、英语和中文。",
    "telemedicine.faqs.2.q": "我的英语 / 韩语不太好怎么办？",
    "telemedicine.faqs.3.a": "不能。远程协诊用于初步评估、第二诊疗意见和随访。手术与治疗仍需到院。",
    "telemedicine.faqs.3.q": "这能替代面诊吗？",
    "telemedicine.faqs.4.a": "通话前通过安全链接上传。MRI、CT、病理报告由专科医生在通话中实时判读。",
    "telemedicine.faqs.4.q": "如何共享我的病历？",
    "telemedicine.faqs.5.a": "通常本国保险不予报销。咨询费直接支付。部分私人保险计划可报销——欢迎咨询。",
