    "km.viewAll": "查看全部韩方治疗项目",
    "km.hero.title": "探索韩国传统韩方医学",
    "km.hero.highlight": "千年疗愈传承",
    "km.hero.subtitle": "体验韩国独特的整体医疗体系——草药配方、针灸以及为国际患者量身定制的健康项目。",
    "km.cta": "获取免费治疗方案",
    "km.section.whatIs": "什么是韩方医学？",
    "km.section.whatIsDesc": "韩方（韓方）是韩国拥有千年历史的独特传统医疗体系。它结合草药、针灸、艾灸和拔罐疗法，通过恢复身体平衡来治疗疾病根源。目前在韩国政府许可的正规医院中开展。",
    "km.section.whyKorea": "为什么选择在韩国体验传统医学？",
    "km.section.hospitals": "合作韩方医院",
    "km.section.treatments": "韩方治疗项目",
    "km.section.faq": "常见问题",
    "km.faq.q1": "什么是韩医（韩方）？",
    "km.faq.a1": "韩医（한방/韓方）是拥有1,000多年历史的韩国独有传统医学体系。通过草药、针灸、艾灸和拔罐恢复身体平衡，治疗疾病的根本原因。",
    "km.faq.q2": "韩医治疗安全吗？",
    "km.faq.a2": "是的。韩国所有韩方医院均由保健福祉部许可并监管。韩医师拥有博士级学位，并使用经认证、质量受控的药材，遵循严格的安全规程。",
    "km.faq.q3": "与中医有什么不同？",
    "km.faq.a3": "虽然历史渊源相同，但韩医（韓方）独立发展，具有四象体质医学（사상체질의학）、独特的处方，并在韩国国家医疗体系下受到更严格的监管。",
    "km.faq.q4": "我需要会说韩语吗？",
    "km.faq.a4": "不需要。合作医院提供英语和中文翻译服务，并由国际患者协调员全程协助。",
    "km.faq.q5": "我需要在韩国停留多久？",
    "km.faq.a5": "治疗时长因项目而异：免疫增强与养生项目通常需要5-7天，产后调理需2-4周。可根据您的日程定制。",
    "km.diff.regulated": "政府监管体系",
    "km.diff.regulatedDesc": "所有韩方医院均经保健福祉部许可，遵守严格的安全标准。",
    "km.diff.unique": "四象体质医学",
    "km.diff.uniqueDesc": "韩国独有的体质医学体系，将患者分为四种体质类型进行个性化治疗。",
    "km.diff.modern": "传统与现代融合",
    "km.diff.modernDesc": "韩方医院将传统疗法与现代诊断技术相结合，提供循证医疗服务。",
