    "costCalc.quoteText": "費用はがんの種類・進行度・計画により異なります。記録をお送りいただければ、無料で個別見積もりを作成します（義務なし）。",
    "costCalc.quoteTitle": "正確な費用は？無料相談で。",
    "faqData.category.consultation": "相談",
    "faqData.category.payment": "支払い",
    "faqData.category.privacy": "プライバシー",
    "faqData.category.recovery": "回復・免疫ケア",
    "faqData.category.service": "healwith について",
    "faqData.category.treatment": "治療",
    "faqData.category.visa": "ビザと滞在",
    "faqData.consultation1.a": "営業日基準で1日以内、希望言語で返信します。緊急の場合は数時間以内に対応します。",
    "faqData.consultation1.q": "問い合わせへの返信はどれくらい早いですか？",
    "faqData.consultation2.a": "はい。問診後、マッチした専門医との事前ビデオ相談を手配します。リアルタイム医療通訳付きです。",
    "faqData.consultation3.q": "診療記録（CT・生検結果）はどうやって送りますか？",
    "faqData.consultation3.a": "お問い合わせフォームの2段階目で添付してください — PDF・JPG・PNG、最大10ファイルです。後からでも送れます。受付後に担当コーディネーターからご連絡し、同じお問い合わせにファイルを追加できます。ファイルは暗号化して保管し、お選びになった病院にのみ共有します。容量が大きい場合は分割するか、主要な資料から送ってください — 診断要約・病理結果・最近の画像検査があれば、まず始められます。",
    "faqData.consultation2.q": "渡航前に医師と話せますか？",
    "faqData.payment1.a": "患者様は治療費のみを病院に直接お支払いいただきます（韓国ウォン、クレジットカード・現金・送金）。healwithは患者様にサービス料やコーディネーション料を請求しません——当社へのお支払いはございません。",
    "faqData.payment1.q": "支払いはどのように？",
    "faqData.payment2.a": "はい。韓国「医療海外進出および外国人患者誘致支援法」第8条第2項により、誘致医療機関（病院）は診療契約の前に診療契約書と予想診療費を案内する義務があります。healwith は登録誘致事業者として、その見積書をご希望言語または英語でお渡しし、確認をお手伝いします。",
    "faqData.payment3.q": "キャンセルした場合はどうなりますか？",
    "faqData.payment3.a": "healwith にお支払いいただく費用はありません。当社は患者様から手数料を一切いただかないため、当社側のキャンセル費用は0円です — ご相談・病院マッチング・事前ビデオ相談・見積書はすべて無料で、治療契約書に署名される前であればいつでも費用なく中止できます。すでに病院へ直接予約金をお支払いの場合は、その病院の返金規定が適用されます。規定は署名前にお渡しする見積書に記載されています。",
    "faqData.payment2.q": "契約前に見積書はもらえますか？",
    "faqData.privacy1.a": "エンドツーエンド暗号化（TLS 1.3、AES-256）。韓国PIPA、カザフスタン94-V、EU GDPRに準拠。機微な医療データは別途明示的同意を得て、選択した病院のみと共有し、サービス完了後は削除されます。",
    "faqData.privacy1.q": "医療データはどう保護されますか？",
    "faqData.privacy2.a": "はい。DPO（admin@healwith.co.kr）にいつでも閲覧・訂正・削除を請求できます。病院保有の診療記録は医療法§22により通常10年間保存されます。",
    "faqData.privacy2.q": "後でデータを削除できますか？",
    "faqData.recovery1.a": "協診の大学・総合病院では診断・手術・抗がん治療を受けます。提携の免疫ケア病院（免疫韓方病院）ではその後の回復を支えます——韓方免疫治療、疼痛リハビリ、栄養管理、副作用管理など。healwithはこの両方を一つの連続ケア経路でつなぎます。",
    "faqData.recovery1.q": "手術病院と免疫ケア（韓方）病院はどう違いますか？",
    "faqData.recovery2.a": "韓方免疫治療、温熱療法、疼痛リハビリ、オーダーメイドの栄養・入院食、体力・心理の回復支援など——手術や抗がん剤後のがんの種類と状態に合わせて。具体的なプログラムは病院の医療陣が決定します。",
    "faqData.recovery2.q": "免疫ケア病院ではどんな治療を受けられますか？",
    "faqData.recovery3.a": "手術や抗がん剤の直後の数週間は免疫力が最も低く、副作用が現れる時期です。栄養管理、免疫・痛みの管理、落ち着いた環境での体系的な回復ケアは、一人で管理するより回復をスムーズに支える場合があります。healwithは手術と回復を途切れなくつなぎ、全工程で通訳を支援します。",
    "faqData.recovery3.q": "手術後すぐ帰国せず、韓国で回復するほうが良いですか？",
    "faqData.recovery4.a": "状態によります——入院でも通院でも可能です。通常は数日から数週間です。コーディネーターと医療陣が治療日程・ビザに合わせて計画を立て、回復の経過に応じて調整します。",
    "faqData.recovery4.q": "回復ケアは入院が必要ですか？期間はどれくらいですか？",
    "faqData.service1.a": "healwithは、外国人がん患者が韓国のトップがん専門病院で治療を受けられるよう支援するメディカルコンシェルジュプラットフォームです。病院の選定、ビザ支援、通訳、全工程のコーディネートを行います。",
    "faqData.service1.q": "healwithとは何ですか？",
    "faqData.service2.a": "いいえ。healwithはソウル特別市長が登録した外国人患者誘致事業者（登録番号 A-2026-01-02-06761）です。韓国の認可医療機関とつなぎますが、診断・治療は病院の医療陣が行います。",
    "faqData.service2.q": "healwithは病院ですか？",
    "faqData.service3.a": "healwithのご利用は患者様には無料です。初回のお問い合わせから治療後のフォローまで、サービス料やコーディネーション料を患者様に請求することはありません。患者様は治療費のみを病院に直接お支払いいただき、healwithは提携病院から報酬を受け取り運営しています。",
    "faqData.service3.q": "healwithの費用は？",
    "faqData.treatment1.a": "主な対応：胃がん、乳がん、肝がん、肺がん、甲状腺がん、大腸がん——韓国は世界トップクラスの生存率を誇ります。他の症例もパートナー病院ネットワークで対応可能です。",
    "faqData.treatment1.q": "healwithが対応するがんの種類は？",
    "faqData.treatment2.a": "診断・ステージ・言語・予算・日程に基づき、マッチングが2–3の病院を提案。コーディネーターが確認し、最終決定はあなたが行います。",
    "faqData.treatment2.q": "自分に合った病院はどう選ぶ？",
    "faqData.visa1.a": "国籍によります。多くの場合、医療ビザ（C-3-3短期（90日以内）、G-1長期）が必要です。healwithが招聘状を発行し、申請全体をサポートします。",
    "faqData.visa1.q": "韓国での治療にビザは必要ですか？",
    "faqData.visa2.a": "はい。同伴家族のビザ申請（通常C-3-3またはC-3-9）と、治療期間中の宿泊手配も行います。",
    "faqData.visa2.q": "介護者や家族を同伴できますか？",
    "faqPage.all": "すべて",
    "faqPage.contactBody": "コーディネーターが営業日基準で1日以内に、ご希望の言語で個別にお答えします。",
    "faqPage.contactBtn": "会話を始める",
