    "careJourney.heroCta": "相談を始める",
    "careJourney.heroLede": "healwithは病院を一つ選ぶだけのサービスではありません。来韓前のオンライン相談から、診断・手術・免疫回復、帰国後の管理まで——がん治療の全過程を一緒に設計し、寄り添います。",
    "careJourney.heroTitle": "診断から回復まで、\n途切れない治療の旅",
    "careJourney.modelBody": "がん治療は一度の手術で終わりません。healwithは免疫・リハビリ専門の韓方病院と、手術・抗がん中心の協診大学病院を一つのネットワークでつなぎ、診断結果に応じて必要な治療を段階的につなげます。患者様は毎回新しい病院を探す必要がありません。",
