    "km.viewAll": "韓方施術すべて見る",
    "km.hero.title": "韓国伝統韓方医学を体験",
    "km.hero.highlight": "千年の癒しの伝統",
    "km.hero.subtitle": "韓国独自のホリスティック医療システムを体験 — 漢方薬、鍼灸、海外患者向けのオーダーメイドウェルネスプログラム。",
    "km.cta": "無料治療プランを受け取る",
    "km.section.whatIs": "韓方医学とは？",
    "km.section.whatIsDesc": "韓方（韓方）は1,000年以上の歴史を持つ韓国固有の伝統医療体系です。漢方薬、鍼灸、灸、カッピングを組み合わせ、体のバランスを整えて病気の根本原因を治療します。現在、韓国政府認可の医療機関で実施されています。",
    "km.section.whyKorea": "なぜ韓国で伝統医学を？",
    "km.section.hospitals": "提携韓方病院",
    "km.section.treatments": "韓方治療プログラム",
    "km.section.faq": "よくある質問",
    "km.faq.q1": "韓医学（韓方）とは何ですか？",
    "km.faq.a1": "韓医学（한방/韓方）は1,000年以上の歴史を持つ韓国独自の伝統医学体系です。漢方薬・鍼・灸・カッピングで体のバランスを回復し、病気の根本原因を治療します。",
    "km.faq.q2": "韓医学は安全ですか？",
    "km.faq.a2": "はい。韓国のすべての韓方病院は保健福祉部の許可と規制を受けています。韓医師は博士級の学位を持ち、認証済み・品質管理された生薬を用いて厳格な安全手順に従います。",
    "km.faq.q3": "中医学（中国伝統医学）とどう違いますか？",
    "km.faq.a3": "歴史的なルーツは共通ですが、韓医学（韓方）は独自に発展し、四象体質医学（사상체질의학）や独自の処方を持ち、韓国の国家医療制度の下でより厳格に管理されています。",
    "km.faq.q4": "韓国語を話せる必要がありますか？",
    "km.faq.a4": "いいえ。提携病院は英語・中国語の通訳サービスと国際患者コーディネーターを提供し、滞在中ずっとサポートします。",
    "km.faq.q5": "韓国にはどのくらい滞在すればよいですか？",
    "km.faq.a5": "治療期間はプログラムによって異なります。免疫強化・ウェルネスプログラムは通常5-7日、産後ケアは2-4週間です。日程に合わせて調整できます。",
    "km.diff.regulated": "政府認可制度",
    "km.diff.regulatedDesc": "すべての韓方病院は保健福祉部の認可を受け、厳格な安全基準を遵守しています。",
    "km.diff.unique": "四象体質医学",
    "km.diff.uniqueDesc": "韓国固有の体質医学システムで、患者を4つの体質に分類し個別化治療を行います。",
    "km.diff.modern": "伝統と現代の融合",
    "km.diff.modernDesc": "韓方病院は伝統療法と最新の診断技術を組み合わせ、エビデンスに基づく医療を提供します。",
