    "costCalc.disclaimer": "⚠️ Этапы лечения и стоимость зависят от состояния пациента. Точная стоимость и план предоставляются бесплатно после изучения медицинских документов. Иммунная/реабилитационная терапия корейской медицины является поддерживающей и не гарантирует излечения.",
