    "telemedicine.ctaPrimary": "Записаться на консультацию",
    "telemedicine.ctaSecondary": "Как это работает",
    "telemedicine.ctaSection.body": "Бесплатно и без обязательств. \nОпишите свой случай — мы свяжемся с вами в течение 24 часов.",
    "telemedicine.ctaSection.btn": "Записаться на консультацию",
    "telemedicine.ctaSection.title": "Ваша первая консультация возможна уже на этой неделе.",
    "telemedicine.docsEyebrow": "Документы которые рекомендуется подготовить заранее",
    "telemedicine.docsItems.1": "Медицинское заключение / диагноз",
    "telemedicine.docsItems.2": "Результат гистологии (биопсии)",
    "telemedicine.docsItems.3": "Подтверждение операции",
