    "telemedicine.docsItems.5": "История назначений и приёма лекарств",
    "telemedicine.docsNote": "С подготовленными документами врач даст точные рекомендации. На первом шаге достаточно контактных данных — координатор направит вас дальше.",
    "telemedicine.eyebrow": "Телемедицина · Консьерж онкологической помощи",
    "telemedicine.faqEyebrow": "Частые вопросы",
    "telemedicine.faqs.1.a": "Нет. Для телемедицины достаточно современного браузера (Chrome, Safari, Edge) на ПК, планшете или телефоне.",
    "telemedicine.faqs.1.q": "Нужно ли устанавливать приложение?",
    "telemedicine.faqs.2.a": "Мы обеспечиваем участие медицинского переводчика при звонке. Доступны русский, казахский, английский и китайский.",
    "telemedicine.faqs.2.q": "А если я плохо владею английским / корейским?",
    "telemedicine.faqs.3.a": "Нет. Телемедицина используется для первичной оценки, получения второго мнения и наблюдения. Хирургическое вмешательство и лечение всё равно требуют личного визита.",
    "telemedicine.faqs.3.q": "Может ли это заменить очную консультацию?",
    "telemedicine.faqs.4.a": "Перед звонком загрузите материалы по защищённой ссылке. Специалист разбирает МРТ, КТ и гистологию во время консультации.",
    "telemedicine.faqs.4.q": "Как передать медицинские записи?",
    "telemedicine.faqs.5.a": "В большинстве случаев страховка вашей страны не действует. Оплата осуществляется напрямую. Частные планы иногда компенсируют — мы подскажем детали.",
    "telemedicine.faqs.5.q": "Покрывается ли это страховкой?",
    "telemedicine.faqs.6.a": "Данные передаются по сквозному шифрованию AES‑256. Хранение соответствует PIPA §28‑8 и стандартам GDPR.",
    "telemedicine.faqs.6.q": "Как обеспечивается конфиденциальность?",
    "telemedicine.features.1.body": "Высокое качество связи без установки приложений.",
    "telemedicine.features.1.title": "HD видео и звук",
    "telemedicine.features.2.body": "Корейский ↔ русский / казахский / английский / китайский.",
    "telemedicine.features.2.title": "Медицинский перевод в реальном времени",
    "telemedicine.features.3.body": "МРТ, КТ, гистология разбираются в прямом эфире во время звонка.",
    "telemedicine.features.3.title": "Обмен документами",
    "telemedicine.features.4.body": "Сертифицированные онкологи ведущих клиник Кореи.",
