    "telemedicine.features.7.title": "Сопровождение координатора",
    "telemedicine.features.8.body": "Консультация по фиксированной стоимости. Без скрытых платежей. Поездка — по вашему выбору.",
    "telemedicine.features.8.title": "Прозрачная цена",
    "telemedicine.featuresEyebrow": "Что входит",
    "telemedicine.heroLede": "Не нужны ни виза, ни авиабилет. Видеоконсультация в реальном времени с онкологами Кореи — из Алматы, Астаны, Москвы или из любой точки мира. Решайте, ехать ли, только после того, как узнаете.",
    "telemedicine.heroTitle": "Встретьтесь с корейским онкологом ещё до того, как сядете в самолёт.",
