    "careJourney.closingBody": "Достаточно одной минуты. Координатор свяжется с вами на удобном языке.",
    "careJourney.closingCta": "Запросить консультацию",
    "careJourney.closingTitle": "Решим вместе, с чего начать ваш путь",
    "careJourney.eyebrow": "Консьерж обеспечивающий полный цикл поддержки",
    "careJourney.heroCta": "Начать консультацию",
    "careJourney.heroLede": "healwith — это не просто сервис по подбору клиники. \nОт онлайн‑консультации до приезда, через диагностику, операцию и иммунотерапию, до ухода после возвращения — мы вместе с вами планируем весь путь лечения рака и сопровождаем вас.",
    "careJourney.heroTitle": "От диагностики до выздоровления непрерывный маршрут лечения.",
    "careJourney.modelBody": "Лечение онкологического заболевания редко ограничивается одним этапом. После операции следует химиотерапия, после химиотерапии — восстановление. healwith выстраивает маршрут целиком: основное лечение — хирургия, химиотерапия, лучевая терапия — проводится в университетских клиниках Сеула, а поддерживающие и восстановительные программы — в клинике корейской медицины. Вам не нужно на каждом этапе искать новую клинику и заново собирать документы.",
    "careJourney.modelTitle": "Почему «маршрут лечения», а не «подбор клиники»?",
    "careJourney.partnerImmune1": "Immune Hospital Кансо",
    "careJourney.partnerImmune2": "Immune Hospital Синчхон",
    "careJourney.partnerImmune3": "Immune Hospital Кванмён",
    "careJourney.partnerImmune4": "Immune Hospital Сондон",
    "careJourney.partnerImmuneGroupTitle": "Партнёрские клиники корейской медицины",
    "careJourney.partnerLede": "Хирургия и химиотерапия — в университетских клиниках‑партнёрах; иммунный и реабилитационный уход — в Immune Hospital, как часть единой бесшовной сети.",
    "careJourney.partnerTitle": "Наша сеть ведущих клиник",
    "careJourney.partnerUniversity1": "Больница Ихва Сеул",
    "careJourney.partnerUniversity2": "Больница Ихва Мокдон",
    "careJourney.partnerUniversity3": "Больница Куро",
    "careJourney.partnerUniversity4": "Больница Северанс Синчхон",
    "careJourney.partnerUniversityLabel": "Университетские клиники-партнёры",
    "careJourney.stat1Label": "5-летняя выживаемость при раке (2019–2023)",
    "careJourney.stat1Value": "73,7%",
    "careJourney.stat2Label": "Количество иностранных пациентов за 2025 год",
    "careJourney.stat2Value": "2,01 млн+",
    "careJourney.statsSource": "Источники: Национальный онкологический центр Кореи (национальный реестр рака); статистика иностранных пациентов KHIDI",
    "careJourney.statsTitle": "Лечение рака в Корее в цифрах",
    "careJourney.step1Body": "ИИ-консультант и координаторы отвечают на 6 языках. Решите вопросы из дома, до поездки в Корею.",
    "careJourney.step1Title": "Онлайн-консультация",
    "careJourney.step2Body": "Медицинские команды партнёров изучают ваши документы и объясняют возможное направление лечения в Корее.",
    "careJourney.step2Title": "Дистанционная диагностика",
    "careJourney.step3Body": "Если нужна операция — направляем в университетскую больницу; иммунный уход и реабилитация продолжаются в больнице корейской медицины. Мы разрабатываем подходящий маршрут вместе с вами.",
    "careJourney.step3Title": "Разработка маршрута",
    "careJourney.step4Body": "Во время пребывания в Корее координаторы помогают с медицинским переводом, визитами в больницу и бытовыми вопросами.",
    "careJourney.step4Title": "Сопровождение на месте",
    "careJourney.step5Body": "После возвращения домой наблюдение продолжается через дистанционные консультации. Лечение не заканчивается одним визитом.",
    "careJourney.step5Title": "Уход после возвращения",
    "careJourney.stepsTitle": "Ваш маршрут лечения в 5 шагов",
    "careJourney.whyCare1Body": "Специалисты поэтапно управляют ослабленным иммунитетом, болью и побочными эффектами после операции или химиотерапии — с помощью иммунотерапии корейской медицины и программ реабилитации, учитывая ваше состояние.",
    "careJourney.whyCare1Title": "Системный иммунный и реабилитационный уход",
    "careJourney.whyCare2Body": "Стационарное питание и индивидуальный план, подобранные под тип рака и текущее состояние, помогают восстановить силы. Мы также учитываем пищевые предпочтения иностранных пациентов.",
    "careJourney.whyCare2Title": "Индивидуальное питание",
    "careJourney.whyCare3Body": "Спокойная обстановка на этапе восстановления, перевод и сопровождение координатора для иностранных пациентов — на всех этапах пребывания.",
    "careJourney.whyCare3Title": "Спокойная среда и языковая поддержка",
    "careJourney.whyCareLede": "Лечение не заканчивается операцией или химиотерапией — впереди период восстановления. Клиника корейской медицины в программе healwith работает именно с этим этапом, в согласовании с вашим онкологом.",
    "careJourney.whyCareTitle": "После операции: почему необходимы иммунный и реабилитационный уход",
    "claimPage.agencyLabel": "Направлено через",
    "claimPage.alreadyClaimedHint": "Случай уже привязан к аккаунту. Войдите, чтобы проверить.",
    "claimPage.alreadyClaimedTitle": "Этот случай уже привязан",
    "claimPage.cancerLabel": "Диагноз",
    "claimPage.claimedHint": "Теперь вы можете видеть ход лечения, документы и чат в личном кабинете.",
    "claimPage.claimedTitle": "Готово!",
