    "seo.home.title": "healwith | Лечение рака в Корее для иностранных пациентов",
    "seo.home.desc": "Консьерж по лечению рака в Корее для иностранных пациентов — видеоконсультация с ведущими онкологами, поддержка на 6 языках, сопровождение на всех этапах.",
    "seo.treatments.title": "Лечение рака — корейская и интегративная медицина | healwith",
    "seo.treatments.desc": "Специализированное лечение 6 видов рака — молочной железы, гинекологического, ЖКТ, печени, лёгких, щитовидной железы — с интегративной иммунотерапией.",
    "seo.hospitals.title": "Партнёрские клиники Кореи — проверенные и надёжные | healwith",
    "seo.hospitals.desc": "healwith сотрудничает с Immune Hospital для иммунотерапии и ведущими онкологическими клиниками Кореи для операций и лечения.",
    "seo.telemedicine.title": "Телемедицина — видеоконсультация с корейскими врачами | healwith",
    "seo.telemedicine.desc": "Видеоконсультация в реальном времени с ведущими онкологами Кореи и переводом на 6 языков. Свяжитесь до поездки.",
    "seo.careJourney.title": "Путь лечения — от диагностики до восстановления | healwith",
    "seo.careJourney.desc": "Полный путь лечения рака в Корее — от диагностики и консультации до лечения, визы и наблюдения после лечения.",
    "seo.insurance.title": "Лечение рака в Корее по страховке | healwith",
    "seo.insurance.desc": "Страховые программы при критических заболеваниях покрывают лечение рака в Корее — медицинскую помощь, перелёт и проживание. healwith берёт на себя организацию: клиники, перевод и сопровождение.",
    "seo.faq.title": "Вопросы и ответы — что чаще всего спрашивают пациенты | healwith",
    "seo.faq.desc": "Ответы о консультации, лечении в Корее, медицинской визе, оплате и конфиденциальности — всё, что спрашивают иностранные пациенты до поездки.",
    "seo.visa.title": "Медицинская виза в Корею — C-3-3 и G-1-10 | healwith",
    "seo.visa.desc": "Какая медицинская виза нужна, какие документы подготовить, сроки оформления и контакты консульства — для пациентов, едущих на лечение в Корею.",
    "seo.about.title": "О healwith — консьерж по лечению рака в Корее",
    "seo.about.desc": "healwith связывает иностранных пациентов с проверенными клиниками Кореи: видеоконсультация с онкологом, перевод на 6 языков, сопровождение от диагностики до восстановления.",
    "seo.contact.title": "Связаться с нами — пациентам и партнёрам | healwith",
    "seo.contact.desc": "Напишите нам о лечении в Корее, втором мнении онколога или о партнёрстве с клиниками и агентствами. Отвечаем на вашем языке.",
    "seo.terms.title": "Условия использования | healwith",
    "seo.terms.desc": "Условия пользования сервисами healwith: медицинский консьерж, подбор клиники и переводческое сопровождение.",
    "seo.privacy.title": "Политика конфиденциальности | healwith",
    "seo.privacy.desc": "Как healwith собирает, использует, шифрует и защищает ваши персональные и медицинские данные.",
