    "common.loadMore": "Загрузить ещё",
    "common.clearAll": "Очистить всё",
    "km.viewAll": "Все программы корейской медицины",
    "km.hero.title": "Откройте для себя традиционную корейскую медицину",
    "km.hero.highlight": "Более 1000 лет целительных традиций",
    "km.hero.subtitle": "Ощутите уникальную холистическую медицину Кореи — травяные формулы, акупунктура и персональные wellness-программы для иностранных пациентов.",
    "km.cta": "Получить бесплатный план лечения",
    "km.section.whatIs": "Что такое корейская медицина?",
    "km.section.whatIsDesc": "Корейская медицина (한방/韓方) — это уникальная традиционная медицинская система Кореи с более чем 1000-летней историей. Она сочетает фитотерапию, акупунктуру, мокса-терапию и баночные процедуры для лечения первопричины заболевания через восстановление баланса в организме. Сегодня она практикуется в лицензированных больницах под регулированием правительства Кореи.",
    "km.section.whyKorea": "Почему Корея для традиционной медицины?",
    "km.section.hospitals": "Партнёрские клиники корейской медицины",
    "km.section.treatments": "Программы лечения корейской медицины",
    "km.section.faq": "Часто задаваемые вопросы",
    "km.faq.q1": "Что такое корейская медицина (ханбан)?",
    "km.faq.a1": "Корейская медицина (한방/韓方) — уникальная традиционная медицинская система Кореи с историей более 1,000 лет. Использует травяные препараты, иглоукалывание, прижигание и банки, чтобы лечить первопричину болезни, восстанавливая баланс организма.",
    "km.faq.q2": "Безопасна ли корейская медицина?",
    "km.faq.a2": "Да. Все клиники корейской медицины в Корее лицензированы и регулируются Министерством здравоохранения и социального обеспечения. Врачи имеют степень доктора и соблюдают строгие протоколы безопасности, используя сертифицированное сырьё с контролем качества.",
    "km.faq.q3": "Чем она отличается от традиционной китайской медицины?",
    "km.faq.a3": "Хотя у них общие исторические корни, корейская медицина (韓方) развивалась самостоятельно: её отличают конституциональная медицина Сасан (사상체질의학), собственные травяные рецептуры и более строгое регулирование в рамках национальной системы здравоохранения Кореи.",
    "km.faq.q4": "Нужно ли мне говорить по-корейски?",
    "km.faq.a4": "Нет. Клиники-партнёры предоставляют перевод на английский и китайский языки, а координаторы по работе с иностранными пациентами сопровождают вас на протяжении всего визита.",
    "km.faq.q5": "Как долго нужно оставаться в Корее?",
    "km.faq.a5": "Продолжительность зависит от программы: программы укрепления иммунитета и велнес обычно занимают 5-7 дней, послеродовое восстановление — 2-4 недели. Программы можно адаптировать под ваш график.",
    "km.diff.regulated": "Государственное регулирование",
    "km.diff.regulatedDesc": "Все клиники корейской медицины лицензированы и контролируются Министерством здравоохранения, строго соблюдая стандарты безопасности.",
    "km.diff.unique": "Уникальная сасанская медицина",
    "km.diff.uniqueDesc": "Корейская конституциональная медицина классифицирует пациентов по четырём типам телосложения для персонализированного лечения.",
    "km.diff.modern": "Современная интеграция",
    "km.diff.modernDesc": "Клиники корейской медицины сочетают традиционные методы с современной диагностикой, обеспечивая доказательный подход.",
