    "telemedicine.docsItems.5": "Дәрі тағайындау тарихы",
    "telemedicine.docsNote": "Бұл құжаттар кеңесті дәлірек етеді. Алдымен байланыс деректерін берсеңіз де жеткілікті — координатор кеңес барысында қалғанын түсіндіреді.",
    "telemedicine.eyebrow": "Телемедицина · Онкологиялық күтім консьержі",
    "telemedicine.faqEyebrow": "Жиі қойылатын сұрақтар",
    "telemedicine.faqs.1.a": "Жоқ. Телемедицина ПК, планшет немесе телефондағы кез келген заманауи браузерде (Chrome, Safari, Edge) жұмыс істейді.",
    "telemedicine.faqs.1.q": "Қосымша орнату керек пе?",
    "telemedicine.faqs.2.a": "Қоңырауға кәсіби медициналық аудармашы қосылады. Орыс, қазақ, ағылшын және қытай тілдерін қолдаймыз.",
    "telemedicine.faqs.2.q": "Ағылшын / корей тілім нашар болса ше?",
    "telemedicine.faqs.3.a": "Жоқ. Телемедицина бастапқы бағалау, екінші пікір және бақылау үшін. Операция мен ем әлі де сапарды талап етеді.",
    "telemedicine.faqs.3.q": "Бұл бетпе-бет кеңесті алмастыра ма?",
    "telemedicine.faqs.4.a": "Қоңырауға дейін қауіпсіз сілтеме арқылы жүктейсіз. МРТ, КТ, гистологияны маман тікелей талдайды.",
    "telemedicine.faqs.4.q": "Медициналық жазбаларды қалай беремін?",
    "telemedicine.faqs.5.a": "Әдетте еліңіздің сақтандыруы жаппайды. Кеңес ақысы тікелей төленеді. Кейбір жеке жоспарлар өтейді — бізден сұраңыз.",
    "telemedicine.faqs.5.q": "Сақтандыру жабады ма?",
    "telemedicine.faqs.6.a": "Барлық трафик ұштан-ұшқа AES-256 шифрланады. Жазбалар PIPA §28-8 (Корея) және GDPR деңгейіндегі стандарттарға сай.",
    "telemedicine.faqs.6.q": "Құпиялылық қалай қамтамасыз етіледі?",
    "telemedicine.features.1.body": "Өте төмен кідірісті WebRTC. Қосымша орнатудың қажеті жоқ.",
