    "telemedicine.features.2.body": "Корей ↔ орыс / қазақ / ағылшын / қытай.",
    "telemedicine.features.2.title": "Тікелей медициналық аударма",
    "telemedicine.features.3.body": "МРТ, КТ, гистология қоңырау кезінде тікелей талданады.",
