    "telemedicine.features.4.title": "Онколог мамандар",
    "telemedicine.features.5.body": "Ұштан-ұшқа AES-256, PIPA §28-8 талаптарына сай.",
    "telemedicine.features.5.title": "Медициналық деңгейдегі қауіпсіздік",
    "telemedicine.features.6.body": "Аккаунт қажет емес — науқас тек сілтеме арқылы кіреді.",
    "telemedicine.features.6.title": "Қонақ ретінде кіру",
    "telemedicine.features.7.body": "Әр сессиядан кейін жазбаша қорытынды мен келесі қадам жоспары жіберіледі.",
    "telemedicine.features.7.title": "Координатор сүйемелдеуі",
    "telemedicine.features.8.body": "Тұрақты кеңес ақысы. Жасырын төлемдер жоқ. Сапар — сіздің таңдауыңыз.",
    "telemedicine.features.8.title": "Ашық баға",
