    "careJourney.heroCta": "Кеңесті бастау",
    "careJourney.heroLede": "healwith — жай ғана аурухана таңдап беретін қызмет емес. Келмес бұрынғы онлайн кеңестен бастап диагностика, операция, иммундық қалпына келу, оралғаннан кейінгі күтімге дейін — біз сізбен бірге обырды емдеудің бүкіл жолын жоспарлаймыз және серік боламыз.",
    "careJourney.heroTitle": "Диагностикадан сауығуға дейін —\nүзіліссіз емдеу жолы",
    "careJourney.modelBody": "Обырды емдеу бір операциямен бітпейді. healwith иммундық және оңалту маманданған корей медицинасы ауруханалары мен хирургия, химиотерапияға бағытталған серіктес университет ауруханаларын бір желіге біріктіреді — әр кезең сіздің диагнозыңызға сай жалғасады. Сізге әр жолы жаңа аурухана іздеудің қажеті жоқ.",
