    "careJourney.statsSource": "Дереккөздер: Корея Ұлттық онкология орталығы (ұлттық обыр тіркелімі); KHIDI шетелдік науқастар статистикасы",
    "careJourney.statsTitle": "Кореядағы обыр емі — сандармен",
    "careJourney.step1Body": "ЖИ кеңесшісі мен координаторлар 6 тілде жауап береді. Кореяға келмес бұрын сұрақтарыңызды үйден шешіңіз.",
    "careJourney.step1Title": "Онлайн кеңес",
    "careJourney.step2Body": "Серіктес медициналық топтар сіздің құжаттарыңызды қарап, Кореядағы емдеу бағытын түсіндіреді.",
    "careJourney.step2Title": "Қашықтан диагностика",
    "careJourney.step3Body": "Операция қажет болса университет ауруханасына жолдаймыз; иммундық күтім мен оңалту корей медицинасы ауруханасында жалғасады. Сізге сай жолды бірге жоспарлаймыз.",
    "careJourney.step3Title": "Емдеу жолын жоспарлау",
    "careJourney.step4Body": "Кореяда болу кезінде координаторлар медициналық аударма, ауруханаға еріп жүру және тұрмыстық қолдау көрсетеді.",
    "careJourney.step4Title": "Жерде серік болу",
    "careJourney.step5Body": "Үйге оралғаннан кейін де қашықтан кеңес арқылы бақылау жалғасады. Емдеу бір сапармен бітпейді.",
    "careJourney.step5Title": "Оралғаннан кейінгі күтім",
    "careJourney.stepsTitle": "Сіздің емдеу жолыңыз, 5 қадам",
    "careJourney.whyCare1Body": "Мамандар операциядан немесе химиотерапиядан кейінгі әлсіреген иммунитет, ауырсыну мен жанама әсерлерді корей медицинасы иммунотерапиясы мен оңалту арқылы кезең-кезеңімен басқарады.",
    "careJourney.whyCare1Title": "Жүйелі иммундық және оңалту күтімі",
    "careJourney.whyCare2Body": "Обыр түрі мен жағдайға сай стационарлық тамақ пен тамақтану жоспары күшті қалпына келтіруге көмектеседі. Шетелдік науқастардың тамақ мәдениетін де ескереміз.",
    "careJourney.whyCare2Title": "Жеке тамақтану",
    "careJourney.whyCare3Body": "Қарбалас ірі ауруханадан айырмашылығы — тыныш ортада қалпына келуге назар аудара аласыз, аударма мен координатор қасыңызда.",
    "careJourney.whyCare3Title": "Тыныш орта және тілдік қолдау",
    "careJourney.whyCareLede": "Обырды емдеу операциямен немесе химиотерапиямен бітпейді. Әлсіреген иммунитет пен жанама әсерлерді қалпына келу кезінде қалай басқаратыныңыз келесі кезеңді айқындайды. healwith серіктес корей медицинасы ауруханалары осы кезеңге маманданған.",
