    "seo.home.title": "healwith | Шетелдік науқастарға Кореяда қатерлі ісікті емдеу",
    "seo.home.desc": "Шетелдік науқастарға арналған Кореядағы онкологиялық емдеу қызметі — жетекші онкологтармен бейнекеңес, 6 тілде қолдау, толық сүйемелдеу.",
    "seo.treatments.title": "Қатерлі ісікті емдеу — корейлік және интегративті ем | healwith",
    "seo.treatments.desc": "6 түрлі қатерлі ісікті мамандандырылған емдеу — сүт безі, гинекологиялық, ас қорыту, бауыр, өкпе, қалқанша без — интегративті иммунотерапиямен.",
    "seo.hospitals.title": "Серіктес ауруханалар — тексерілген корей клиникалары | healwith",
    "seo.hospitals.desc": "healwith серіктес ауруханалары — Immune Hospital иммунотерапиясы және хирургия мен онкологияға арналған мамандандырылған ауруханалар.",
    "seo.telemedicine.title": "Телемедицина — корей дәрігерлерімен бейнекеңес | healwith",
    "seo.telemedicine.desc": "Кореяның жетекші онкологтарымен нақты уақыттағы бейнекеңес, 6 тілде аударма. Сапарға дейін байланысыңыз.",
    "seo.careJourney.title": "Емдеу жолы — диагностикадан сауығуға дейін | healwith",
    "seo.careJourney.desc": "Кореядағы қатерлі ісікті емдеудің толық жолы — диагностика мен кеңестен емдеуге, визаға және емнен кейінгі бақылауға дейін.",
    "seo.insurance.title": "Сақтандыру бойынша Кореяда қатерлі ісікті емдеу | healwith",
    "seo.insurance.desc": "Ауыр науқастарға арналған сақтандыру бағдарламалары Кореядағы қатерлі ісік емін өтей алады — ем, ұшу және тұру. healwith корей жағын ұйымдастырады: аурухана, аударма және сүйемелдеу.",
    "seo.faq.title": "Сұрақ-жауап — науқастар жиі қоятын сұрақтар | healwith",
    "seo.faq.desc": "Кеңес, Кореяда емделу, медициналық виза, төлем және құпиялық туралы жауаптар — шетелдік науқастар сапарға дейін жиі сұрайтынның бәрі.",
    "seo.visa.title": "Кореяға медициналық виза — C-3-3 және G-1-10 | healwith",
    "seo.visa.desc": "Қандай медициналық виза керек, қандай құжаттар дайындау қажет, өтінішті қарау мерзімі және елшілік байланыстары — емделуге Кореяға баратын науқастар үшін.",
    "seo.about.title": "healwith туралы — Кореядағы онкологиялық емдеу консьержі",
    "seo.about.desc": "healwith шетелдік науқастарды тексерілген корей клиникаларымен байланыстырады: онкологпен бейнекеңес, 6 тілде аударма, диагностикадан қалпына келуге дейін сүйемелдеу.",
    "seo.contact.title": "Бізбен байланыс — науқастар мен серіктестерге | healwith",
    "seo.contact.desc": "Кореяда емделу, онкологтың екінші пікірі немесе клиникалар мен агенттіктермен серіктестік туралы жазыңыз. Сіздің тіліңізде жауап береміз.",
    "seo.terms.title": "Пайдалану шарттары | healwith",
    "seo.terms.desc": "healwith қызметтерін — медициналық консьерж, клиника таңдау және аударма сүйемелдеуін — пайдалану шарттары.",
    "seo.privacy.title": "Құпиялық саясаты | healwith",
    "seo.privacy.desc": "healwith сіздің дербес және медициналық деректеріңізді қалай жинайды, пайдаланады, шифрлайды және қорғайды.",
    "seo.cookies.title": "Cookie файлдары саясаты | healwith",
    "seo.cookies.desc": "healwith қандай cookie файлдарын пайдаланады, олар не үшін керек және сіз оларды қалай басқара аласыз.",
    "seo.medicalDisclaimer.title": "Медициналық ескерту | healwith",
    "seo.medicalDisclaimer.desc": "healwith ақпарат беріп, сүйемелдейді, бірақ диагноз, емдеу немесе дәрі тағайындауды алмастырмайды. Әрқашан лицензиясы бар дәрігерге кеңесіңіз.",
    "seo.inquiry.title": "Өтініш қалдыру — Кореядағы емге байланыс | healwith",
    "seo.inquiry.desc": "healwith-ке өтінішті бастаңыз — ЖИ-көмекшісін, жеке координаторды немесе өтініш формасын таңдаңыз.",
    "seo.immune.title": "Immune Hospital — Кореядағы интегративті иммундық ем | healwith",
    "seo.immune.desc": "Immune Hospital — қатерлі ісік науқастарына корей медицинасының интегративті иммунотерапиясы (ITCRN 5 өсі), healwith негізгі серіктесі.",
