    "seo.patientDash.title": "Науқастың жеке кабинеті | healwith",
    "seo.patientDash.desc": "Кеңестер, медициналық құжаттар, симптом журналы және келесі қадамдар — бәрі healwith жеке кабинетінде.",
    "seo.patientConsults.title": "Бейнекеңес тарихы | healwith",
    "seo.patientConsults.desc": "Корей дәрігерлерімен өткен және жоспарланған бейнекеңестер — медициналық аудармамен.",
    "seo.patientSymptoms.title": "Симптом журналы | healwith",
    "seo.patientSymptoms.desc": "Симптомдарыңызды күн сайын жазып отырыңыз — координатор мен дәрігер сауығу барысын бақылайды.",
    "seo.patientDocs.title": "Медициналық құжаттар | healwith",
    "seo.patientDocs.desc": "Корей дәрігеріне қажет құжаттарды жүктеп, сақтап отырыңыз: томограмма суреттері, гистология қорытындысы және емдеу көшірмелері.",
    "seo.patientEducation.title": "Науқастарға арналған оқу материалдары | healwith",
    "seo.patientEducation.desc": "Ем аяқталғаннан кейінгі өмірге арналған материалдар: дәрі қабылдау, тамақтану, дене жүктемесі, қауіпті белгілер және психологиялық қолдау.",
    "seo.patientAccount.title": "Аккаунт және құпиялылық | healwith",
    "seo.patientAccount.desc": "healwith аккаунтыңыз бен деректеріңізді басқарыңыз: сақталған мәліметтерді қараңыз немесе аккаунтты жойыңыз.",
    "seo.patientChat.title": "ЖИ-агентпен кеңес | healwith",
    "seo.patientChat.desc": "healwith ЖИ-агентінен Кореядағы емдеу нұсқалары, клиникалар және құны туралы ана тіліңізде сұраңыз.",
    "seo.patientEstimates.title": "Шығындар сметалары | healwith",
    "seo.patientEstimates.desc": "Кореядағы емделудің болжамды құны және үйлестіруші ресімдейтін клиниканың ресми сметасы.",
    "seo.patientEstimateDetail.title": "Смета туралы толық ақпарат | healwith",
    "seo.patientEstimateDetail.desc": "Осы сметаның тармақ бойынша егжей-тегжейі: не кіреді, жалпы сома және оны қалай мақұлдауға болады.",
    "seo.patientRebooking.title": "Қайта жазылуды басқару | healwith",
    "seo.patientRebooking.desc": "Симптом журналыңыз, бақылау кестеңіз және дәрігер ұсынысы бойынша автоматты ұсынылған қайта қабылдаулар.",
    "seo.patientVisa.title": "Медициналық виза | healwith",
    "seo.patientVisa.desc": "Корея медициналық визасының рәсімделуін қадағалаңыз және емдеу жоспарыңызға қай виза түрі сай екенін біліңіз.",
    "seo.patientVisaApps.title": "Виза өтінімдерім | healwith",
    "seo.patientVisaApps.desc": "Әр виза өтінімінің қай кезеңде екенін көріңіз және үйлестіруші сұраған құжаттарды жүктеңіз.",
    "seo.patientVisaAppDetail.title": "Виза өтінімі туралы толық ақпарат | healwith",
    "seo.patientVisaAppDetail.desc": "Осы өтінімнің күйі, әлі қажет құжаттар және корей клиникасының шақыру хаты.",
    "seo.patientMessages.title": "Хабарламалар | healwith",
