    "seo.notifications.title": "Хабарламалар | healwith",
    "seo.notifications.desc": "Емделу жаңалықтары, координатор хабарламалары және қабылдау еске салғыштары — бір жерде.",
    "seo.login.title": "Кіру | healwith",
