    "km.viewAll": "Барлық корей медицина бағдарламалары",
    "km.hero.title": "Дәстүрлі корей медицинасын ашыңыз",
    "km.hero.highlight": "1000 жылдан астам шипа дәстүрі",
    "km.hero.subtitle": "Кореяның бірегей холистикалық медицинасын сезініңіз — шөп формулалары, акупунктура және шетелдік науқастарға арналған жеке сауықтыру бағдарламалары.",
    "km.cta": "Тегін емдеу жоспарын алу",
    "km.section.whatIs": "Корей медицинасы дегеніміз не?",
    "km.section.whatIsDesc": "Корей медицинасы (한방/韓方) — Кореяның 1000 жылдан астам тарихы бар бірегей дәстүрлі медициналық жүйесі. Ол шөп терапиясын, акупунктураны, моксибусияны және банка терапиясын біріктіре отырып, ағзадағы тепе-теңдікті қалпына келтіру арқылы аурудың түбірін емдейді. Бүгінде ол Корей үкіметі реттейтін лицензиясы бар ауруханаларда жүргізіледі.",
    "km.section.whyKorea": "Неліктен дәстүрлі медицина үшін Корея?",
    "km.section.hospitals": "Серіктес корей медицина ауруханалары",
    "km.section.treatments": "Корей медицинасы емдеу бағдарламалары",
    "km.section.faq": "Жиі қойылатын сұрақтар",
    "km.faq.q1": "Корей медицинасы (ханбан) дегеніміз не?",
    "km.faq.a1": "Корей медицинасы (한방/韓方) — 1,000 жылдан астам тарихы бар Кореяның өзіндік дәстүрлі медицина жүйесі. Шөп дәрілері, ине терапиясы, күйдіру (мокса) және банка қою арқылы ағзаның тепе-теңдігін қалпына келтіріп, аурудың түпкі себебін емдейді.",
    "km.faq.q2": "Корей медицинасы қауіпсіз бе?",
    "km.faq.a2": "Иә. Кореядағы барлық корей медицинасы клиникалары Денсаулық сақтау және әл-ауқат министрлігінің лицензиясымен реттеледі. Дәрігерлер докторлық дәрежеге ие және сапасы бақыланатын сертификатталған шөп шикізатымен қатаң қауіпсіздік хаттамаларын сақтайды.",
    "km.faq.q3": "Дәстүрлі қытай медицинасынан айырмашылығы неде?",
    "km.faq.a3": "Тарихи тамырлары ортақ болғанымен, корей медицинасы (韓方) дербес дамыған: оның ерекшелігі — Сасан конституциялық медицинасы (사상체질의학), өзіндік шөп рецептуралары және Кореяның ұлттық денсаулық сақтау жүйесі аясындағы қатаңырақ реттеу.",
    "km.faq.q4": "Корей тілін білуім керек пе?",
    "km.faq.a4": "Жоқ. Серіктес клиникалар ағылшын және қытай тілдеріне аударма қызметін көрсетеді, ал халықаралық науқастар үйлестірушілері сапар бойы көмектеседі.",
    "km.faq.q5": "Кореяда қанша уақыт болуым керек?",
